  1→import React, { useState, useCallback, useEffect } from "react";
  2→import { useAuth } from "@/hooks/useAuth";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import AppHeader from "@/components/AppHeader";
  5→import AuthDialog from "@/components/AuthDialog";
  6→import JobSidebar from "@/components/JobSidebar";
  7→import JobDetailView from "@/components/JobDetailView";
  8→import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
  9→import { toast } from "sonner";
 10→
 11→export interface PastJob {
 12→  id: string;
 13→  title: string | null;
 14→  job_description: string;
 15→  status: string;
 16→  created_at: string;
 17→  resume_count: number;
 18→  jd_analysis_json: any;
 19→  dynamic_weights_json: Record<string, number> | null;
 20→  inbox_email: string | null;
 21→}
 22→
 23→export interface Result {
 24→  id: string;
 25→  resume_id: string;
 26→  overall_score: number;
 27→  missing_skills: string[];
 28→  summary: string | null;
 29→  interview_questions: any;
 30→  filename: string;
 31→  file_path: string | null;
 32→  candidate_name: string | null;
 33→  candidate_email?: string | null;
 34→  candidate_phone?: string | null;
 35→  candidate_location?: string | null;
 36→  // Dynamic scoring fields
 37→  hard_fit?: boolean;
 38→  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
 39→  confidence?: number;
 40→  strengths_json?: string[];
 41→  gaps_json?: string[];
 42→  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string; matched_preferred?: string[]; missing_preferred?: string[] };
 43→  matched_must_haves?: string[];
 44→  missing_must_haves?: string[];
 45→  scoring_version?: string;
 46→  pending?: boolean;
 47→  parsed_json?: any;
 48→}
 49→
 50→export interface ExistingResume {
 51→  id: string;
 52→  filename: string;
 53→  file_path: string | null;
 54→  candidate_name: string | null;
 55→  created_at: string;
 56→}
 57→
 58→const Index = () => {
 59→  const { user } = useAuth();
 60→
 61→  const [pastJobs, setPastJobs] = useState<PastJob[]>([]);
 62→  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
 63→  const [loadingPastJobs, setLoadingPastJobs] = useState(false);
 64→  const [results, setResults] = useState<Result[]>([]);
 65→  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
 66→  const [authOpen, setAuthOpen] = useState(false);
 67→
 68→  const selectedJob = pastJobs.find((j) => j.id === selectedJobId) ?? null;
 69→
 70→  const fetchPastJobs = useCallback(async () => {
 71→    if (!user) return;
 72→    setLoadingPastJobs(true);
 73→    try {
 74→      const { data: jobs } = await supabase
 75→        .from("jobs")
 76→        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
 77→        .eq("user_id", user.id)
 78→        .order("created_at", { ascending: false })
 79→        .limit(50);
 80→      if (jobs) {
 81→        setPastJobs(jobs.map((j: any) => ({
 82→          id: j.id,
 83→          title: j.title,
 84→          job_description: j.job_description,
 85→          status: j.status,
 86→          created_at: j.created_at,
 87→          resume_count: j.resumes?.[0]?.count ?? 0,
 88→          jd_analysis_json: j.jd_analysis_json,
 89→          dynamic_weights_json: j.dynamic_weights_json,
 90→          inbox_email: j.inbox_email ?? null,
 91→        })));
 92→      }
 93→    } catch (err) {
 94→      toast.error("Failed to load jobs");
 95→    } finally {
 96→      setLoadingPastJobs(false);
 97→    }
 98→  }, [user]);
 99→
100→  useEffect(() => {
101→    fetchPastJobs();
102→  }, [fetchPastJobs]);
103→
104→  const loadJobData = async (jobId: string) => {
105→    setSelectedJobId(jobId);
106→    try {
107→      const [resumesRes, resumeListRes] = await Promise.all([
108→        supabase
109→          .from("resumes")
110→          .select("id, filename, file_path, candidate_name, created_at")
111→          .eq("job_id", jobId)
112→          .order("created_at", { ascending: false }),
113→        supabase
114→          .from("resumes")
115→          .select("id, filename, file_path, candidate_name, parsed_json")
116→          .eq("job_id", jobId),
117→      ]);
118→
119→      const resumes = resumesRes.data ?? [];
120→      setExistingResumes(resumes);
121→
122→      const resumeData = (resumeListRes.data ?? []) as Array<{
123→        id: string;
124→        filename: string;
125→        file_path: string | null;
126→        candidate_name: string | null;
127→        parsed_json?: any;
128→      }>;
129→      if (resumeData.length === 0) {
130→        setResults([]);
131→        return;
132→      }
133→
134→      const resumeIds = resumeData.map((r) => r.id);
135→      const { data: resultData } = await supabase
136→        .from("results")
137→        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
138→        .in("resume_id", resumeIds);
139→
140→      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
141→      const allMerged: Result[] = (resultData ?? []).map((r: any) => {
142→        const resume = resumeMap.get(r.resume_id);
143→        const parsed = resume?.parsed_json as any;
144→        return {
145→          ...r,
146→          overall_score: r.overall_score ?? 0,
147→          missing_skills: r.missing_skills ?? [],
148→          filename: resume?.filename ?? "Unknown",
149→          file_path: resume?.file_path ?? null,
150→          candidate_name: resume?.candidate_name ?? null,
151→          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
152→          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
153→          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
154→          parsed_json: resume?.parsed_json ?? null,
155→        };
156→      });
157→      // Deduplicate by resume_id — keep highest scoring result per resume
158→      const deduped = new Map<string, Result>();
159→      for (const r of allMerged) {
160→        const existing = deduped.get(r.resume_id);
161→        if (!existing || r.overall_score > existing.overall_score) {
162→          deduped.set(r.resume_id, r);
163→        }
164→      }
165→      const merged = Array.from(deduped.values());
166→      merged.sort((a, b) => b.overall_score - a.overall_score);
167→      setResults(merged);
168→    } catch (err) {
169→      toast.error("Failed to load job data");
170→    }
171→  };
172→
173→  const handleNewJob = () => {
174→    setSelectedJobId(null);
175→    setResults([]);
176→    setExistingResumes([]);
177→  };
178→
179→  const handleJobCreated = (job: PastJob) => {
180→    setPastJobs((prev) => [job, ...prev]);
181→    setSelectedJobId(job.id);
182→    loadJobData(job.id);
183→  };
184→
185→  const handleRenameJob = (jobId: string, newTitle: string) => {
186→    setPastJobs((prev) =>
187→      prev.map((j) => (j.id === jobId ? { ...j, title: newTitle } : j))
188→    );
189→  };
190→
191→  const handleDeleteJob = async (jobId: string) => {
192→    try {
193→      await supabase.from("resumes").delete().eq("job_id", jobId);
194→      await supabase.from("jobs").delete().eq("id", jobId);
195→      setPastJobs((prev) => prev.filter((j) => j.id !== jobId));
196→      if (selectedJobId === jobId) handleNewJob();
197→      toast.success("Job deleted");
198→    } catch {
199→      toast.error("Failed to delete job");
200→    }
201→  };
202→
203→  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
204→    setPastJobs((prev) =>
205→      prev.map((j) => (j.id === jobId ? { ...j, ...updates } : j))
206→    );
207→  };
208→
209→  const requireAuth = useCallback(() => {
210→    if (!user) { setAuthOpen(true); return true; }
211→    return false;
212→  }, [user]);
213→
214→  return (
215→    <SidebarProvider className="h-svh overflow-hidden">
216→      <JobSidebar
217→        pastJobs={pastJobs}
218→        selectedJobId={selectedJobId}
219→        loadingPastJobs={loadingPastJobs}
220→        onSelectJob={loadJobData}
221→        onNewJob={handleNewJob}
222→        onRenameJob={handleRenameJob}
223→        onDeleteJob={handleDeleteJob}
224→        onAuthRequired={() => setAuthOpen(true)}
225→        isAuthenticated={!!user}
226→      />
227→
228→      <SidebarInset className="h-svh overflow-y-auto">
229→        <AppHeader />
230→        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
231→          <SidebarTrigger />
232→          <span className="ml-2 text-sm font-medium text-muted-foreground">Job History</span>
233→        </div>
234→        <JobDetailView
235→          selectedJobId={selectedJobId}
236→          selectedJob={selectedJob}
237→          results={results}
238→          setResults={setResults}
239→          existingResumes={existingResumes}
240→          setExistingResumes={setExistingResumes}
241→          onJobCreated={handleJobCreated}
242→          onAuthRequired={() => setAuthOpen(true)}
243→          isAuthenticated={!!user}
244→          onJobUpdated={handleJobUpdated}
245→        />
246→      </SidebarInset>
247→
248→      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
249→    </SidebarProvider>
250→  );
251→};
252→
253→export default Index;
254→

  1→import { useState } from "react";
  2→import { Button } from "@/components/ui/button";
  3→import { Badge } from "@/components/ui/badge";
  4→import { Checkbox } from "@/components/ui/checkbox";
  5→import { TableCell, TableRow } from "@/components/ui/table";
  6→import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
  7→import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
  8→import {
  9→  ChevronDown, ChevronUp, Phone, Mail, MapPin,
 10→  FileText, Archive
 11→} from "lucide-react";
 12→import { toast } from "sonner";
 13→import type { Result } from "@/pages/Index";
 14→import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
 15→// Sub-components
 16→import CandidateSummary from "@/components/candidate/CandidateSummary";
 17→import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
 18→import ExperiencePanel from "@/components/candidate/ExperiencePanel";
 19→import EducationPanel from "@/components/candidate/EducationPanel";
 20→import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
 21→import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
 22→import InterviewQuestionsPanel from "@/components/candidate/InterviewQuestionsPanel";
 23→import StageTracker from "@/components/candidate/StageTracker";
 24→import type { HiringStage } from "@/hooks/useStageTracker";
 25→
 26→interface CandidateRowProps {
 27→  result: Result;
 28→  index: number;
 29→  isExpanded: boolean;
 30→  isSelected: boolean;
 31→  jobTitle?: string | null;
 32→  onToggleRow: (id: string) => void;
 33→  onToggleSelect: (resumeId: string) => void;
 34→  onDownload: (filePath: string, filename: string) => void;
 35→  onDelete: (resumeId: string, filePath: string | null) => void;
 36→  onDismiss: (resumeId: string) => void;
 37→  formatCandidateName: (filename: string) => string;
 38→  currentStage?: HiringStage | null;
 39→  stageUpdatedAt?: string | null;
 40→  onStageChange?: (resumeId: string, stage: HiringStage) => void;
 41→  onRewriteJd?: () => void;
 42→}
 43→
 44→const getScoreColor = (score: number) => {
 45→  if (score >= 70) return "bg-score-skills";
 46→  if (score >= 40) return "bg-warning";
 47→  return "bg-destructive";
 48→};
 49→
 50→const getScoreTextColor = (score: number) => {
 51→  if (score >= 70) return "text-score-skills";
 52→  if (score >= 40) return "text-warning";
 53→  return "text-destructive";
 54→};
 55→
 56→const STAGE_BADGE_CLASSES: Record<string, string> = {
 57→  applied: "border-border bg-muted/50 text-muted-foreground",
 58→  screened: "border-blue-200 bg-blue-50 text-blue-700 dark:border-blue-700 dark:bg-blue-900/20 dark:text-blue-400",
 59→  interview: "border-purple-200 bg-purple-50 text-purple-700 dark:border-purple-700 dark:bg-purple-900/20 dark:text-purple-400",
 60→  offer: "border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-700 dark:bg-amber-900/20 dark:text-amber-400",
 61→  hired: "border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400",
 62→  rejected: "border-red-200 bg-red-50 text-red-700 dark:border-red-700 dark:bg-red-900/20 dark:text-red-400",
 63→};
 64→
 65→const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
 66→  if (score >= 70) return { label: "Strong", variant: "success" };
 67→  if (score >= 40) return { label: "Good", variant: "warning" };
 68→  return { label: "Weak", variant: "destructive" };
 69→};
 70→
 71→const getRankDisplay = (index: number) => {
 72→  if (index < 3) {
 73→    const colors = [
 74→      "bg-score-overall text-white",
 75→      "bg-muted-foreground/60 text-white",
 76→      "bg-warning text-white",
 77→    ];
 78→    return (
 79→      <span className={`inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-bold ${colors[index]}`}>
 80→        {index + 1}
 81→      </span>
 82→    );
 83→  }
 84→  return (
 85→    <span className="inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-medium bg-muted text-muted-foreground">
 86→      {index + 1}
 87→    </span>
 88→  );
 89→};
 90→
 91→const CandidateRow = ({
 92→  result: r,
 93→  index,
 94→  isExpanded,
 95→  isSelected,
 96→  jobTitle,
 97→  onToggleRow,
 98→  onToggleSelect,
 99→  onDownload,
100→  onDelete,
101→  onDismiss,
102→  formatCandidateName,
103→  currentStage,
104→  stageUpdatedAt,
105→  onStageChange,
106→  onRewriteJd,
107→}: CandidateRowProps) => {
108→  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
109→  const strength = !r.pending ? getStrengthLabel(r.overall_score) : null;
110→
111→  return (
112→    <>
113→    <Collapsible open={isExpanded} onOpenChange={() => onToggleRow(r.id)} asChild>
114→      <>
115→        {/* Collapsed Row */}
116→        <TableRow className="cursor-pointer hover:bg-muted/50 transition-colors" onClick={() => !r.pending && onToggleRow(r.id)}>
117→          <TableCell onClick={(e) => e.stopPropagation()}>
118→            <Checkbox checked={isSelected} onCheckedChange={() => onToggleSelect(r.resume_id)} />
119→          </TableCell>
120→          <TableCell className="text-center">
121→            {r.pending ? <span className="text-sm text-muted-foreground">—</span> : getRankDisplay(index)}
122→          </TableCell>
123→          <TableCell className="font-medium">
124→            <div className="flex flex-col gap-0.5">
125→              <div className="flex items-center gap-1.5 flex-wrap">
126→                <span className="text-sm">{r.candidate_name || formatCandidateName(r.filename)}</span>
127→                {!r.pending && currentStage && currentStage !== "applied" && (
128→                  <Badge
129→                    variant="outline"
130→                    className={`text-[10px] px-1.5 py-0 h-4 capitalize border font-medium ${STAGE_BADGE_CLASSES[currentStage] ?? ""}`}
131→                  >
132→                    {currentStage}
133→                  </Badge>
134→                )}
135→              </div>
136→              {r.candidate_location && (
137→                <span className="flex items-center gap-1 text-xs text-muted-foreground">
138→                  <MapPin className="h-3 w-3" /> {r.candidate_location}
139→                </span>
140→              )}
141→            </div>
142→          </TableCell>
143→          <TableCell>
144→            {r.pending ? (
145→              <Badge variant="outline" className="text-xs">Pending</Badge>
146→            ) : (
147→              <div className="flex items-center gap-2">
148→                <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[100px]">
149→                  <div
150→                    className={`h-full rounded-full transition-all ${getScoreColor(r.overall_score)}`}
151→                    style={{ width: `${Math.min(r.overall_score, 100)}%` }}
152→                  />
153→                </div>
154→                <span className={`text-sm font-semibold tabular-nums min-w-[3ch] ${getScoreTextColor(r.overall_score)}`}>
155→                  {r.overall_score?.toFixed(0)}%
156→                </span>
157→              </div>
158→            )}
159→          </TableCell>
160→          <TableCell>
161→            <div className="flex flex-wrap items-center gap-1">
162→              {!r.pending && strength && (
163→                <Badge variant={strength.variant} className="text-[10px]">
164→                  {strength.label}
165→                </Badge>
166→              )}
167→              {!r.pending && r.scoring_version === "heuristic" && (
168→                <TooltipProvider delayDuration={300}>
169→                  <Tooltip>
170→                    <TooltipTrigger asChild>
171→                      <span className="inline-flex items-center text-[10px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground font-medium cursor-default">
172→                        Quick
173→                      </span>
174→                    </TooltipTrigger>
175→                    <TooltipContent className="max-w-xs text-xs">
176→                      This candidate was ranked by keyword matching. Top candidates receive full AI scoring.
177→                    </TooltipContent>
178→                  </Tooltip>
179→                </TooltipProvider>
180→              )}
181→              {!r.pending && r.scoring_version?.startsWith("rule-") && (
182→                <TooltipProvider delayDuration={300}>
183→                  <Tooltip>
184→                    <TooltipTrigger asChild>
185→                      <span className="inline-flex items-center text-[10px] px-1.5 py-0.5 rounded bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 font-medium cursor-default">
186→                        Rule
187→                      </span>
188→                    </TooltipTrigger>
189→                    <TooltipContent className="max-w-xs text-xs">
190→                      Scored using deterministic rule-based algorithm. Same input always produces the same score.
191→                    </TooltipContent>
192→                  </Tooltip>
193→                </TooltipProvider>
194→              )}
195→            </div>
196→          </TableCell>
197→          <TableCell>
198→            <div className="flex items-center gap-0.5" onClick={(e) => e.stopPropagation()}>
199→              <TooltipProvider delayDuration={300}>
200→                {/* Phone */}
201→                <Tooltip>
202→                  <TooltipTrigger asChild>
203→                    {r.candidate_phone ? (
204→                      <a
205→                        href={`tel:${r.candidate_phone}`}
206→                        onClick={(e) => {
207→                          if (!/Mobi|Android/i.test(navigator.userAgent)) {
208→                            e.preventDefault();
209→                            navigator.clipboard.writeText(r.candidate_phone!);
210→                            toast.success("Phone number copied!");
211→                          }
212→                        }}
213→                      >
214→                        <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary" aria-label="Call candidate">
215→                          <Phone className="h-3.5 w-3.5" />
216→                        </Button>
217→                      </a>
218→                    ) : (
219→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled aria-label="Phone not available">
220→                        <Phone className="h-3.5 w-3.5" />
221→                      </Button>
222→                    )}
223→                  </TooltipTrigger>
224→                  <TooltipContent>{r.candidate_phone ? `Copy: ${r.candidate_phone}` : "Phone not found in resume"}</TooltipContent>
225→                </Tooltip>
226→
227→                {/* Email */}
228→                <Tooltip>
229→                  <TooltipTrigger asChild>
230→                    {r.candidate_email ? (
231→                      <Button
232→                        variant="ghost"
233→                        size="icon"
234→                        className="h-7 w-7 text-muted-foreground hover:text-primary"
235→                        onClick={() => setEmailDialogOpen(true)}
236→                        aria-label="Email candidate"
237→                      >
238→                        <Mail className="h-3.5 w-3.5" />
239→                      </Button>
240→                    ) : (
241→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled aria-label="Email not available">
242→                        <Mail className="h-3.5 w-3.5" />
243→                      </Button>
244→                    )}
245→                  </TooltipTrigger>
246→                  <TooltipContent>{r.candidate_email ? `Email: ${r.candidate_email}` : "Email not found in resume"}</TooltipContent>
247→                </Tooltip>
248→
249→                {/* Download */}
250→                <Tooltip>
251→                  <TooltipTrigger asChild>
252→                    {r.file_path ? (
253→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary" onClick={() => onDownload(r.file_path!, r.filename)} aria-label="Download resume">
254→                        <FileText className="h-3.5 w-3.5" />
255→                      </Button>
256→                    ) : (
257→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled aria-label="No file available">
258→                        <FileText className="h-3.5 w-3.5" />
259→                      </Button>
260→                    )}
261→                  </TooltipTrigger>
262→                  <TooltipContent>{r.file_path ? "Download resume" : "No file"}</TooltipContent>
263→                </Tooltip>
264→
265→                {/* Archive */}
266→                <Tooltip>
267→                  <TooltipTrigger asChild>
268→                    <Button
269→                      variant="ghost" size="icon"
270→                      className="h-7 w-7 text-muted-foreground hover:text-amber-500"
271→                      onClick={() => onDismiss(r.resume_id)}
272→                      aria-label="Archive candidate"
273→                    >
274→                      <Archive className="h-3.5 w-3.5" />
275→                    </Button>
276→                  </TooltipTrigger>
277→                  <TooltipContent>Archive candidate</TooltipContent>
278→                </Tooltip>
279→              </TooltipProvider>
280→
281→              {!r.pending && (
282→                <CollapsibleTrigger asChild>
283→                  <Button variant="ghost" size="icon" className="h-7 w-7">
284→                    {isExpanded ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
285→                  </Button>
286→                </CollapsibleTrigger>
287→              )}
288→            </div>
289→          </TableCell>
290→        </TableRow>
291→
292→        {/* Expanded Detail — New Layout */}
293→        {!r.pending && (
294→          <CollapsibleContent asChild>
295→            <TableRow className="bg-muted/30 hover:bg-muted/30">
296→              <TableCell colSpan={6} className="p-5">
297→                <div className="space-y-4">
298→                  {/* 1. Summary + Stage Tracker — unified overview card */}
299→                  {(() => {
300→                    const hasSummary = !!(r.explanation_json?.summary || r.summary);
301→                    if (!hasSummary && !onStageChange) return null;
302→                    return (
303→                      <div className="rounded-lg border bg-background overflow-hidden">
304→                        {hasSummary && (
