332→                  {/* 4. JD Aligned — full width (includes AI suggestion + Rewrite JD) */}
333→                  <JDAlignedPanel result={r} onRewriteJd={onRewriteJd} />
334→
335→                  {/* 7. Interview Questions — collapsible */}
336→                  <InterviewQuestionsPanel result={r} />
337→                </div>
338→              </TableCell>
339→            </TableRow>
340→          </CollapsibleContent>
341→        )}
342→      </>
343→    </Collapsible>
344→
345→    {r.candidate_email && (
346→      <EmailOutreachDialog
347→        open={emailDialogOpen}
348→        onOpenChange={setEmailDialogOpen}
349→        candidateName={r.candidate_name || r.filename}
350→        candidateEmail={r.candidate_email}
351→        jobTitle={jobTitle || "Open Position"}
352→        matchScore={Math.round(r.overall_score ?? 0)}
353→        resumeId={r.resume_id}
354→        jobId={r.id}
355→      />
356→    )}
357→    </>
358→  );
359→};
