132→function mergeSkillSynonyms(adminSynonyms: Record<string, string[]>) {
133→  const merged = { ...SKILL_SYNONYMS };
134→  for (const [canonical, syns] of Object.entries(adminSynonyms)) {
135→    const key = canonical.toLowerCase().trim();
136→    merged[key] = [...new Set([...(merged[key] || []), ...syns.map(s => s.toLowerCase().trim())])];
