154→    const startRaw = role.start || role.start_date || role.from || "";
155→    const endRaw = role.end || role.end_date || role.to || "";
156→
157→    const startDate = parseDate(String(startRaw), currentYear, currentMonth);
158→    let endDate = parseDate(String(endRaw), currentYear, currentMonth);
159→
160→    // Handle "present", "current", "ongoing" etc.
161→    const endLower = String(endRaw).toLowerCase().trim();
162→    if (!endRaw || endLower === "present" || endLower === "current" || endLower === "ongoing" || endLower === "now" || endLower === "till date" || endLower === "till now") {
163→      endDate = currentYear + (currentMonth - 1) / 12;
164→    }
165→
166→    if (startDate > 0 && endDate > 0 && endDate >= startDate) {
167→      intervals.push({ start: startDate, end: endDate });
168→    }
169→  }
170→
171→  if (intervals.length === 0) return 0;
172→
173→  // Merge overlapping intervals to avoid double-counting
174→  intervals.sort((a, b) => a.start - b.start);
175→  const merged: { start: number; end: number }[] = [intervals[0]];
176→  for (let i = 1; i < intervals.length; i++) {
177→    const last = merged[merged.length - 1];
178→    if (intervals[i].start <= last.end) {
179→      last.end = Math.max(last.end, intervals[i].end);
180→    } else {
181→      merged.push(intervals[i]);
182→    }
183→  }
184→
185→  let totalYears = 0;
186→  for (const iv of merged) {
187→    totalYears += iv.end - iv.start;
188→  }
189→  return Math.round(totalYears * 10) / 10; // 1 decimal
190→}
