241→function scoreEducation(education: any[], levels: EducationLevel[]): { score: number; highestDegree: string } {
242→  if (!Array.isArray(education) || education.length === 0) {
243→    return { score: 0, highestDegree: "none" };
244→  }
245→
246→  let bestScore = 0;
247→  let bestLevel = "unknown";
248→
249→  for (const edu of education) {
250→    const degree = String(edu.degree || edu.qualification || edu.level || "").toLowerCase().trim();
251→    if (!degree) continue;
252→
253→    for (const level of levels) {
254→      for (const alias of level.aliases) {
255→        if (degree.includes(alias.toLowerCase())) {
256→          if (level.score > bestScore) {
257→            bestScore = level.score;
258→            bestLevel = level.level;
259→          }
260→          break;
261→        }
262→      }
263→    }
264→  }
265→
266→  return { score: bestScore, highestDegree: bestLevel };
267→}
